"""/api/v1/reports (P14-T15): PDF, CSV and XLSX files of the user's own data, generated by the
backend from the same services as the screens (DEC-33). Owner-scoped like every other route; each
generated file writes an audit event (kind, format, portfolio; never the figures)."""

import uuid
from datetime import UTC, datetime
from typing import Annotated, Literal

from fastapi import APIRouter, Depends, Query, Response
from pydantic import BaseModel
from sqlalchemy.ext.asyncio import AsyncSession

from app.core.api_responses import UNAUTHORIZED, invalid, not_found
from app.core.audit import Actor, AuditWriter
from app.core.authz import ResourceNotFoundError
from app.core.errors import InvalidValueError
from app.core.money import CURRENCY_PATTERN
from app.db.session import get_session
from app.modules.identity.dependencies import CurrentUserDep
from app.modules.reports.builders import CATALOGUE, build
from app.modules.reports.model import FORMATS, KINDS
from app.modules.reports.render import CONTENT_TYPES, render

router = APIRouter(prefix="/api/v1/reports", tags=["reports"])
SessionDep = Annotated[AsyncSession, Depends(get_session)]


class ReportInfo(BaseModel):
    kind: str
    title: str
    needs_portfolio: bool
    description: str
    formats: list[str]


@router.get("", response_model=list[ReportInfo], responses=UNAUTHORIZED)
async def list_reports(_user: CurrentUserDep) -> list[ReportInfo]:
    """The reports that can be generated, and the formats of each."""
    return [
        ReportInfo(kind=k, title=t, needs_portfolio=n, description=d, formats=list(FORMATS))
        for k, t, n, d in CATALOGUE
    ]


@router.get(
    "/{kind}",
    response_class=Response,
    responses={
        200: {
            "description": "The report file",
            "content": {ct: {} for ct in CONTENT_TYPES.values()},
        },
        **UNAUTHORIZED,
        **not_found("report or portfolio"),
        **invalid("portfolio or currency"),
    },
)
async def get_report(
    kind: str,
    user: CurrentUserDep,
    session: SessionDep,
    format: Annotated[Literal["csv", "xlsx", "pdf"], Query(description="File format")] = "pdf",
    portfolio_id: Annotated[
        uuid.UUID | None, Query(description="Required for portfolio and performance")
    ] = None,
    currency: Annotated[
        str | None,
        Query(
            pattern=CURRENCY_PATTERN,
            description="Report currency where the report converts; default: the account's",
        ),
    ] = None,
) -> Response:
    """A file of the user's own figures with the time they were generated, the currency, the
    data as-of time and the disclosures. The figures equal the screens' for the same request."""
    if kind not in KINDS:
        raise ResourceNotFoundError("report")
    now = datetime.now(UTC)
    report = await build(
        kind, session, user.id, portfolio_id=portfolio_id, currency=currency, now=now
    )
    try:
        content = render(report, format)
    except ValueError as e:  # unreachable: the format is validated above
        raise InvalidValueError(str(e)) from e
    await AuditWriter(session).record(
        "reports.generated",
        Actor.user(user.id),
        resource_type="report",
        resource_id=portfolio_id,
        details={"kind": kind, "format": format, "currency": report.currency},
    )
    await session.commit()
    name = f"wealthsphere-{kind}-{now.date().isoformat()}.{format}"
    return Response(
        content=content,
        media_type=CONTENT_TYPES[format],
        headers={
            "Content-Disposition": f'attachment; filename="{name}"',
            "Cache-Control": "no-store",
            "X-Content-Type-Options": "nosniff",
        },
    )
